#include <iostream>
using namespace std;

// Hàm đệ quy để tính số Fibonacci thứ n
int fibonacci(int n) {
    if (n <= 1) {
        return n;
    } else {
        return fibonacci(n - 1) + fibonacci(n - 2);
    }
}

int main() {
    int n;
    cout << "Nhập vị trí số Fibonacci cần tìm: ";
    cin >> n;
    cout << "Số Fibonacci thứ " << n << " là: " << fibonacci(n) << endl;
    return 0;
}
```

