// Hàm đệ quy tính số Fibonacci thứ n
unsigned long long fibonacci(int n) {
    if (n <= 1)                // Điều kiện dừng: F(0) = 0, F(1) = 1
        return n;
    return fibonacci(n - 1) + fibonacci(n - 2); // Công thức truy hồi
}

