    std::cin >> n;

    if (n < 0) {
        std::cout << "Vui lòng nhập n không âm.\n";
        return 0;
    }

    std::cout << "Số Fibonacci thứ " << n << " là: " << fibonacci(n) << '\n';
    return 0;
}
